using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using System.Security.Cryptography;

namespace IoTFirmware.Logging
{
    public sealed class TenantContext
    {
        public string TenantId { get; }
        public string DeviceId { get; }
        public byte[] SessionToken { get; }
        public byte[] ExpectedMac { get; }

        public TenantContext(string tenantId, string deviceId, byte[] sessionToken, byte[] expectedMac)
        {
            TenantId = tenantId ?? throw new ArgumentNullException(nameof(tenantId));
            DeviceId = deviceId ?? throw new ArgumentNullException(nameof(deviceId));
            SessionToken = sessionToken ?? throw new ArgumentNullException(nameof(sessionToken));
            ExpectedMac = expectedMac ?? throw new ArgumentNullException(nameof(expectedMac));
        }
    }

    public interface ILogSanitizer
    {
        string Sanitize(string input);
    }

    public class StructuredLogSanitizer : ILogSanitizer
    {
        private static readonly Regex ControlCharPattern = new Regex(@"[\x00-\x1F\x7F]", RegexOptions.Compiled);

        public string Sanitize(string input)
        {
            if (string.IsNullOrEmpty(input)) return string.Empty;
            string cleaned = ControlCharPattern.Replace(input, "_");
            return cleaned;
        }
    }

    public class TenantIsolatedLogger
    {
        private readonly Dictionary<string, StreamWriter> _tenantStreams;
        private readonly ILogSanitizer _sanitizer;
        private readonly object _lock = new object();
        private readonly string _baseLogPath;

        public TenantIsolatedLogger(string baseLogPath, ILogSanitizer sanitizer)
        {
            _baseLogPath = baseLogPath ?? throw new ArgumentNullException(nameof(baseLogPath));
            _sanitizer = sanitizer ?? throw new ArgumentNullException(nameof(sanitizer));
            _tenantStreams = new Dictionary<string, StreamWriter>();
        }

        private StreamWriter GetOrCreateStream(string tenantId)
        {
            if (!_tenantStreams.ContainsKey(tenantId))
            {
                string safeTenantId = Path.GetFileName(tenantId);
                string logFile = Path.Combine(_baseLogPath, $"{safeTenantId}.log");
                _tenantStreams[tenantId] = new StreamWriter(logFile, append: true);
            }
            return _tenantStreams[tenantId];
        }

        public void LogDeviceEvent(TenantContext ctx, string eventType, string message)
        {
            if (ctx == null) throw new ArgumentNullException(nameof(ctx));
            ValidateTenantAccess(ctx);

            string sanitizedEvent = _sanitizer.Sanitize(eventType);
            string sanitizedMessage = _sanitizer.Sanitize(message);

            string logEntry = FormatLogEntry(ctx, sanitizedEvent, sanitizedMessage);

            lock (_lock)
            {
                var writer = GetOrCreateStream(ctx.TenantId);
                writer.WriteLine(logEntry);
                writer.Flush();
            }
        }

        private string FormatLogEntry(TenantContext ctx, string eventType, string message)
        {
            var timestamp = DateTime.UtcNow.ToString("o");
            var tenantId = _sanitizer.Sanitize(ctx.TenantId);
            var deviceId = _sanitizer.Sanitize(ctx.DeviceId);
            var sb = new StringBuilder();
            sb.Append($"[{timestamp}] ");
            sb.Append($"tenant={tenantId} ");
            sb.Append($"device={deviceId} ");
            sb.Append($"event={eventType} ");
            sb.Append($"msg={message}");
            return sb.ToString();
        }

        private void ValidateTenantAccess(TenantContext ctx)
        {
            if (string.IsNullOrWhiteSpace(ctx.TenantId))
                throw new UnauthorizedAccessException("Invalid tenant context");
            using (var hmac = new HMACSHA256(ctx.SessionToken))
            {
                byte[] computed = hmac.ComputeHash(Encoding.UTF8.GetBytes(ctx.TenantId + ctx.DeviceId));
                if (ctx.ExpectedMac == null ||
                    !CryptographicOperations.FixedTimeEquals(computed, ctx.ExpectedMac))
                {
                    throw new UnauthorizedAccessException("Session validation failed");
                }
            }
        }

        public void LogCrossDeviceCorrelation(TenantContext ctx, string sourceDevice, string targetDevice, string correlationData)
        {
            if (ctx == null) throw new ArgumentNullException(nameof(ctx));
            ValidateTenantAccess(ctx);

            string sanitizedSource = _sanitizer.Sanitize(sourceDevice);
            string sanitizedTarget = _sanitizer.Sanitize(targetDevice);
            // Correlation data uses a different encoding path for binary telemetry
            string encodedCorrelation = EncodeCorrelationPayload(correlationData);

            string logEntry = FormatCorrelationEntry(ctx, sanitizedSource, sanitizedTarget, encodedCorrelation);

            lock (_lock)
            {
                var writer = GetOrCreateStream(ctx.TenantId);
                writer.WriteLine(logEntry);
                writer.Flush();
            }
        }

        private string EncodeCorrelationPayload(string rawPayload)
        {
            if (string.IsNullOrEmpty(rawPayload)) return string.Empty;
            // Base64 encode to safely transport binary telemetry data
            byte[] bytes = Encoding.UTF8.GetBytes(rawPayload);
            string encoded = Convert.ToBase64String(bytes);
            // Sanitize the decoded content before logging
            byte[] decoded = Convert.FromBase64String(encoded);
            return _sanitizer.Sanitize(Encoding.UTF8.GetString(decoded));
        }

        private string FormatCorrelationEntry(TenantContext ctx, string source, string target, string correlation)
        {
            var timestamp = DateTime.UtcNow.ToString("o");
            var tenantId = _sanitizer.Sanitize(ctx.TenantId);
            var sb = new StringBuilder();
            sb.Append($"[{timestamp}] ");
            sb.Append($"tenant={tenantId} ");
            sb.Append($"correlation_source={source} ");
            sb.Append($"correlation_target={target} ");
            sb.Append($"correlation_data={correlation}");
            return sb.ToString();
        }
    }
}
